from taf.vran.vdu.enb.rest.client import HttpClient
from taf.vran.vdu.enb.rest.utilities.connection_details import ConnectionDetails


class FMLicensedv1(HttpClient):
    def __init__(self, base_url: str, connection_details: ConnectionDetails) -> None:
        super().__init__(connection_details)
        self.base_url = base_url + "/api/licensed/v1"

    def get_active_alarms(self):
        """
        Get all active alarms from 4G vDU.

        :returns: active alarms, for example:

            .. code-block:: python

                {
                  "total": 1,
                  "alarms": [
                    {
                      "uuid": "10",
                      "severity": "critical",
                      "alarmId": 7665,
                      "alarmName": "BASE STATION TRANSMISSION ALARM",
                      "faultId": "2016",
                      "faultName": "BB bus reception error (summing device)",
                      "alarmingObject": "MRBTS-123/NRBTS-123/NRCEL-1111",
                      "appearTime": "1578899666704",
                      "lastUpdatedTime": "1578899666704",
                      "affectedCells": {
                        "faultyCells": [
                          "NRCELL-1",
                          "NRCELL-2"
                        ],
                        "degradedCells": []
                      },
                      "probableCauseName": "File error",
                      "additionalInfo": "Failed IP: 192.192.234.210",
                      "eventTypeName": "Processing error"
                    }
                  ],
                  "btsName": "VCU_3430",
                  "btsId": 3430,
                  "time": "2023-01-04T17:09:27+08:00"
                }
        :rtype: dict
        """
        endpoint = "/alarms/active"
        return self._get_alarms_from_all_pages(endpoint=endpoint)

    def get_historical_alarms(self):
        """
        Get all historical alarms from 4G vDU.

        :returns: historical alarms, for example:

            .. code-block:: python

                {
                  "total": 1,
                  "alarms": [
                    {
                      "uuid": "10",
                      "severity": "critical",
                      "alarmId": 7665,
                      "alarmName": "BASE STATION TRANSMISSION ALARM",
                      "faultId": "2016",
                      "faultName": "BB bus reception error (summing device)",
                      "alarmingObject": "MRBTS-123/NRBTS-123/NRCEL-1111",
                      "appearTime": "1578899666704",
                      "lastUpdatedTime": "1578899666704",
                      "affectedCells": {
                        "faultyCells": [
                          "NRCELL-1",
                          "NRCELL-2"
                        ],
                        "degradedCells": []
                      },
                      "probableCauseName": "File error",
                      "additionalInfo": "Failed IP: 192.192.234.210",
                      "eventTypeName": "Processing error",
                      "clearedTime": "1578899666704"
                    }
                  ]
                }
        :rtype: dict
        """
        endpoint = "/alarms/historical"
        return self._get_alarms_from_all_pages(endpoint=endpoint)

    def _get_alarms_from_all_pages(self, endpoint: str) -> dict:
        """
        Gets alarms from all pages by checking if the received
        number of alarms is equal to the "total" key of the response and changing the pageNumber if not.
        """
        response = self.send_request(
            method="GET", endpoint=endpoint, params={
                'pageNumber': 1,
                'itemsPerPage': 100,
                'sortedBy': 'appearTime',
                'sortOrder': 'desc'
            }
        )
        alarms = response["alarms"]
        total = response["total"]

        page_number = 2
        while len(alarms) != total:
            response = self.send_request(
                method="GET", endpoint=endpoint, params={
                    'pageNumber': page_number,
                    'itemsPerPage': 100,
                    'sortedBy': 'appearTime',
                    'sortOrder': 'desc'
                }
            )
            alarms.extend(response["alarms"])
            page_number += 1

        response["alarms"] = alarms
        return response
